import { ProfilePatch } from './types';

const MAX_DISPLAY_NAME_LENGTH = 40;
const MAX_TAGS_COUNT = 5;
const MAX_TAG_LENGTH = 12;

function throwInvalid(): never {
  throw new Error('invalid profile');
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (!isPlainObject(input)) throwInvalid();

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };

  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') throwInvalid();
  }

  if (Object.hasOwn(input, 'displayName')) {
    const value = input.displayName;
    if (value === null) {
      displayName = { kind: 'set', value: null };
    } else if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed.length < 1 || trimmed.length > MAX_DISPLAY_NAME_LENGTH) throwInvalid();
      displayName = { kind: 'set', value: trimmed };
    } else {
      throwInvalid();
    }
  }

  if (Object.hasOwn(input, 'tags')) {
    const value = input.tags;
    if (value === null) {
      tags = { kind: 'set', value: [] };
    } else if (Array.isArray(value)) {
      if (value.length > MAX_TAGS_COUNT) throwInvalid();
      const seen = new Set<string>();
      const prepared: string[] = [];
      for (const element of value) {
        if (typeof element !== 'string') throwInvalid();
        const trimmed = element.trim();
        if (trimmed.length < 1 || trimmed.length > MAX_TAG_LENGTH) throwInvalid();
        if (seen.has(trimmed)) throwInvalid();
        seen.add(trimmed);
        prepared.push(trimmed);
      }
      tags = { kind: 'set', value: prepared };
    } else {
      throwInvalid();
    }
  }

  return { displayName, tags };
}
