{
  const s = new ProfileService(initial());
  assert.deepEqual(s.patch({ tags: [] }), { displayName: 'before', tags: [] });
  assert.deepEqual(s.patch({ tags: null }), { displayName: 'before', tags: [] });
}
{
  const s = new ProfileService(initial());
  assert.deepEqual(s.patch({ tags: ['  a ', 'b', ' a '] }), { displayName: 'before', tags: ['a', 'b'] });
  const s2 = new ProfileService(initial());
  assert.throws(() => s2.patch({ tags: ['a', ' a '] }), /invalid profile/); // duplicate after trim
  const s3 = new ProfileService(initial());
  assert.throws(() => s3.patch({ tags: ['a'.repeat(13)] }), /invalid profile/); // >12 after trim
  assert.doesNotThrow(() => s3.patch({ tags: ['a'.repeat(12), 'b'.repeat(12), 'c', 'd', 'e'] }));
  const s4 = new ProfileService(initial());
  assert.throws(() => s4.patch({ tags: ['1', '2', '3', '4', '5', '6'] }), /invalid profile/);
  assert.throws(() => s4.patch({ tags: [1] }), /invalid profile/);
  assert.throws(() => s4.patch({ tags: ['ok', null] }), /invalid profile/);
  assert.throws(() => s4.patch({ tags: 'nope' }), /invalid profile/);
  assert.throws(() => s4.patch({ tags: 5 }), /invalid profile/);
  assert.deepEqual(s4.profile, initial());
}
// unknown keys
{
  const s = new ProfileService(initial());
  assert.throws(() => s.patch({ displayName: 'a', extra: 1 }), /invalid profile/);
  assert.throws(() => s.patch({ tags: ['a'], other: null }), /invalid profile/);
  assert.deepEqual(s.profile, initial());
}
// structural validity: no prototypes, arrays, nulls, nonobjects
{
  const bad = [null, [], 5, 'x', true, new Date(), new Map(), new ProfileService(initial()), Object.create({})];
  for (const input of bad) {
    const s = new ProfileService(initial());
    assert.throws(() => s.patch(input), /invalid profile/, String(input));
    assert.deepEqual(s.profile, initial());
  }
  // null-prototype object allowed
  const s = new ProfileService(initial());
  assert.deepEqual(s.patch(Object.assign(Object.create(null), { displayName: 'np' })), { displayName: 'np', tags: ['old'] });
}
// no caller-array reuse, no input mutation
{
  const s = new ProfileService(initial());
  const input = { displayName: 'name', tags: ['a', 'b'] };
  const result = s.patch(input);
  assert.deepEqual(result, { displayName: 'name', tags: ['a', 'b'] });
  result.tags.push('mutation');
  assert.deepEqual(input.tags, ['a', 'b']);
  assert.notStrictEqual(s.profile.tags, input.tags);
  s.profile.tags.push('mutation2');
  assert.deepEqual(input.tags, ['a', 'b']);
  input.displayName = 'changed';
  assert.notEqual(s.profile.displayName, 'changed');
}
// same Error instance/message semantics: Error('invalid profile')
{
  const s = new ProfileService(initial());
  try {
    s.patch('bad');
    assert.fail('should throw');
  } catch (error) {
    assert.ok(error instanceof Error);
    assert.equal(error.message, 'invalid profile');
  }
}
console.log('contracts ok');
